DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = 'qa_attendance_records' AND table_type = 'BASE TABLE')
     AND NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = 'qa_attendance_records_legacy') THEN
    ALTER TABLE qa_attendance_records RENAME TO qa_attendance_records_legacy;
  END IF;
END $$;
-- QA module tables inside Swipr. GENERATED by gen-schema.cjs from the real QA catalog, idempotent.
-- Ids of mirrored rows are the original QA ids. Columns that point at a user hold the SWIPR user id (TEXT).

CREATE TABLE IF NOT EXISTS qa_user_map (
  qa_user_id INTEGER PRIMARY KEY,
  user_id    TEXT NOT NULL,
  match_kind TEXT NOT NULL,
  created_at BIGINT NOT NULL
);
-- two QA accounts can be the same person, so user_id is NOT unique
ALTER TABLE qa_user_map DROP CONSTRAINT IF EXISTS qa_user_map_user_id_key;
CREATE INDEX IF NOT EXISTS qa_user_map_user_idx ON qa_user_map (user_id);

CREATE TABLE IF NOT EXISTS qa_former_staff (
  id TEXT PRIMARY KEY,
  qa_user_id INTEGER UNIQUE NOT NULL,
  display_name TEXT,
  username TEXT,
  role TEXT,
  department TEXT,
  tl_user_id TEXT,
  cc_supervisor_user_id TEXT,
  allowed_departments TEXT,
  allowed_brands TEXT
);

CREATE TABLE IF NOT EXISTS qa_user_profile (
  user_id TEXT PRIMARY KEY,
  qa_role TEXT NOT NULL,
  qa_status TEXT,
  qa_department TEXT,
  tl_user_id TEXT,
  cc_supervisor_user_id TEXT,
  allowed_departments TEXT,
  allowed_brands TEXT
);

CREATE TABLE IF NOT EXISTS qa_evaluations (
  "id" SERIAL,
  "date" text,
  "agent_id" TEXT,
  "qa_id" TEXT,
  "brand" text,
  "call_type" text,
  "final_score" double precision,
  "status" text DEFAULT 'Pending Review'::text,
  "critical_failure" integer DEFAULT 0,
  "data" jsonb,
  "is_wow" integer DEFAULT 0,
  "agent_escalation_status" text,
  "agent_escalation_reason" text,
  "agent_escalation_response" text,
  "agent_escalation_at" timestamp without time zone,
  "last_edited_at" timestamp without time zone,
  "last_edited_by" TEXT,
  "created_at" timestamp without time zone,
  "client_key" text,
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS qa_evaluations_client_key_uq ON qa_evaluations USING btree (client_key) WHERE (client_key IS NOT NULL);

