-- QA's old users table, rebuilt from Swipr users + the QA profile (read only). Ids are Swipr TEXT ids.
CREATE OR REPLACE VIEW qa_users AS
SELECT u.id AS id,
       u.data->>'name' AS display_name,
       u.data->>'username' AS username,
       NULL::text AS password,
       p.qa_role AS role,
       p.qa_department AS department,
       p.tl_user_id AS tl_id,
       p.qa_status AS status,
       p.allowed_departments AS allowed_departments,
       p.allowed_brands AS allowed_brands,
       p.cc_supervisor_user_id AS cc_supervisor_id
FROM users u JOIN qa_user_profile p ON p.user_id = u.id
UNION ALL
-- people who left the company: no Swipr account, but their history keeps a name. id is 'qa:<old QA id>', the same value the mirrored rows point at.
SELECT f.id, f.display_name, f.username, NULL::text, f.role, f.department, f.tl_user_id, 'inactive', f.allowed_departments, f.allowed_brands, f.cc_supervisor_user_id
FROM qa_former_staff f;

-- Attendance: Swipr's punch table is the record. Until cutover QA's own manual rows are mirrored into qa_attendance_records_legacy;
-- the view below shows, per person and Kuwait day, the first IN and the last OUT (within 18h, so night shifts count), and falls back to
-- the legacy row for days that have no punches at all.
CREATE OR REPLACE VIEW qa_attendance_records AS
WITH d AS (
  SELECT a.user_id,
         to_char(to_timestamp(a.ts / 1000.0) AT TIME ZONE 'Asia/Kuwait', 'YYYY-MM-DD') AS date,
         MIN(a.ts) FILTER (WHERE a.kind = 'IN') AS first_in
  FROM attendance a
  WHERE a.user_id IN (SELECT user_id FROM qa_user_profile)
  GROUP BY 1, 2
)
SELECT abs(hashtext(d.user_id || d.date)) AS id, d.user_id, d.date,
       (to_timestamp(d.first_in / 1000.0) AT TIME ZONE 'Asia/Kuwait') AS check_in_at,
       (SELECT to_timestamp(MAX(o.ts) / 1000.0) AT TIME ZONE 'Asia/Kuwait' FROM attendance o
         WHERE o.user_id = d.user_id AND o.kind = 'OUT' AND o.ts > d.first_in AND o.ts < d.first_in + 18 * 3600 * 1000) AS check_out_at
FROM d WHERE d.first_in IS NOT NULL
UNION ALL
SELECT l.id, l.user_id, l.date, l.check_in_at, l.check_out_at FROM qa_attendance_records_legacy l
WHERE NOT EXISTS (SELECT 1 FROM d WHERE d.user_id = l.user_id AND d.date = l.date AND d.first_in IS NOT NULL);
